INSERT IGNORE INTO lg_consents (interview_id, rag_consent, storage_consent, attribution_type, withdrawn, created_at) VALUES ((SELECT interview_id FROM lg_interviews WHERE uuid = (SELECT uuid FROM lg_interviews WHERE interview_id = 544 LIMIT 1)), 1, 1, 'anonymous', 0, NOW());
INSERT IGNORE INTO lg_knowledge_chunks (interview_id, content_type, anonymized_text, embedding_model, status, approved_for_rag, created_at, updated_at) VALUES ((SELECT interview_id FROM lg_interviews WHERE uuid = (SELECT uuid FROM lg_interviews WHERE interview_id = 1 LIMIT 1)), 'summary', 'A personal reflection on a lesson i learned. Key insight: The challenge that taught me the most was learning to step outside my comfort zone and take ownership of my growth. For a long time, I focused mainly on academics, but I realized that knowledge alone was not enough—I needed to apply it to real problems.
INSERT IGNORE INTO lg_knowledge_chunks (interview_id, content_type, anonymized_text, embedding_model, status, approved_for_rag, created_at, updated_at) VALUES ((SELECT interview_id FROM lg_interviews WHERE uuid = (SELECT uuid FROM lg_interviews WHERE interview_id = 7 LIMIT 1)), 'summary', 'A lighthearted story about a major mishap during a wedding ceremony where the ring bearer (a golden retriever) chased a squirrel into a lake.', 'local-semantic-tfidf-v1', 'approved', 1, NOW(), NOW());
INSERT IGNORE INTO lg_knowledge_chunks (interview_id, content_type, anonymized_text, embedding_model, status, approved_for_rag, created_at, updated_at) VALUES ((SELECT interview_id FROM lg_interviews WHERE uuid = (SELECT uuid FROM lg_interviews WHERE interview_id = 7 LIMIT 1)), 'lesson', 'Perfect moments are overrated. The mishaps, mistakes, and unexpected disasters are the things that make life memorable and funny.', 'local-semantic-tfidf-v1', 'approved', 1, NOW(), NOW());
INSERT IGNORE INTO lg_knowledge_chunks (interview_id, content_type, anonymized_text, embedding_model, status, approved_for_rag, created_at, updated_at) VALUES ((SELECT interview_id FROM lg_interviews WHERE uuid = (SELECT uuid FROM lg_interviews WHERE interview_id = 7 LIMIT 1)), 'turning_point', 'Choosing to laugh and jump in the lake to get the dog instead of crying or canceling the reception.', 'local-semantic-tfidf-v1', 'approved', 1, NOW(), NOW());
INSERT IGNORE INTO lg_knowledge_chunks (interview_id, content_type, anonymized_text, embedding_model, status, approved_for_rag, created_at, updated_at) VALUES ((SELECT interview_id FROM lg_interviews WHERE uuid = (SELECT uuid FROM lg_interviews WHERE interview_id = 7 LIMIT 1)), 'outcome', 'It became a legendary family story, wedding pictures of us wet and muddy are our favorites, and it taught us to roll with life\'s punches.', 'local-semantic-tfidf-v1', 'approved', 1, NOW(), NOW());
INSERT IGNORE INTO lg_knowledge_chunks (interview_id, content_type, anonymized_text, embedding_model, status, approved_for_rag, created_at, updated_at) VALUES ((SELECT interview_id FROM lg_interviews WHERE uuid = (SELECT uuid FROM lg_interviews WHERE interview_id = 7 LIMIT 1)), 'advice', 'When things go wrong, ask yourself: \"Will this be funny in ten years?\" If the answer is yes, save yourself the stress and start laughing now.', 'local-semantic-tfidf-v1', 'approved', 1, NOW(), NOW());
INSERT IGNORE INTO lg_knowledge_chunks (interview_id, content_type, anonymized_text, embedding_model, status, approved_for_rag, created_at, updated_at) VALUES ((SELECT interview_id FROM lg_interviews WHERE uuid = (SELECT uuid FROM lg_interviews WHERE interview_id = 7 LIMIT 1)), 'quote', 'Life is a comedy written by an amateur. Don\'t take the script too seriously.', 'local-semantic-tfidf-v1', 'approved', 1, NOW(), NOW());
INSERT IGNORE INTO lg_knowledge_chunks (interview_id, content_type, anonymized_text, embedding_model, status, approved_for_rag, created_at, updated_at) VALUES ((SELECT interview_id FROM lg_interviews WHERE uuid = (SELECT uuid FROM lg_interviews WHERE interview_id = 8 LIMIT 1)), 'summary', 'Lessons learned from recovering from a severe bankruptcy in the early 1990s due to speculative real estate investments. Focuses on learning to live minimally.', 'local-semantic-tfidf-v1', 'approved', 1, NOW(), NOW());
INSERT IGNORE INTO lg_knowledge_chunks (interview_id, content_type, anonymized_text, embedding_model, status, approved_for_rag, created_at, updated_at) VALUES ((SELECT interview_id FROM lg_interviews WHERE uuid = (SELECT uuid FROM lg_interviews WHERE interview_id = 8 LIMIT 1)), 'lesson', 'Wealth is not defined by how much you spend, but by how much freedom you have. Financial security is built by avoiding debt and living below your means.', 'local-semantic-tfidf-v1', 'approved', 1, NOW(), NOW());
INSERT IGNORE INTO lg_knowledge_chunks (interview_id, content_type, anonymized_text, embedding_model, status, approved_for_rag, created_at, updated_at) VALUES ((SELECT interview_id FROM lg_interviews WHERE uuid = (SELECT uuid FROM lg_interviews WHERE interview_id = 8 LIMIT 1)), 'turning_point', 'Losing my home and business in the 1991 market crash, forcing my family to move into a rented two-bedroom apartment.', 'local-semantic-tfidf-v1', 'approved', 1, NOW(), NOW());
INSERT IGNORE INTO lg_knowledge_chunks (interview_id, content_type, anonymized_text, embedding_model, status, approved_for_rag, created_at, updated_at) VALUES ((SELECT interview_id FROM lg_interviews WHERE uuid = (SELECT uuid FROM lg_interviews WHERE interview_id = 8 LIMIT 1)), 'outcome', 'It taught us to find joy in free activities like local library events, hiking, and cooking together, rebuilding a secure savings account slowly.', 'local-semantic-tfidf-v1', 'approved', 1, NOW(), NOW());
INSERT IGNORE INTO lg_knowledge_chunks (interview_id, content_type, anonymized_text, embedding_model, status, approved_for_rag, created_at, updated_at) VALUES ((SELECT interview_id FROM lg_interviews WHERE uuid = (SELECT uuid FROM lg_interviews WHERE interview_id = 8 LIMIT 1)), 'advice', 'Start saving 10% of everything you earn from your very first paycheck. Avoid credit card debt at all costs; if you cannot pay cash, you cannot afford it.', 'local-semantic-tfidf-v1', 'approved', 1, NOW(), NOW());
INSERT IGNORE INTO lg_knowledge_chunks (interview_id, content_type, anonymized_text, embedding_model, status, approved_for_rag, created_at, updated_at) VALUES ((SELECT interview_id FROM lg_interviews WHERE uuid = (SELECT uuid FROM lg_interviews WHERE interview_id = 8 LIMIT 1)), 'quote', 'Losing all my money was the hardest way to find out what actually made me wealthy.', 'local-semantic-tfidf-v1', 'approved', 1, NOW(), NOW());
INSERT IGNORE INTO lg_knowledge_chunks (interview_id, content_type, anonymized_text, embedding_model, status, approved_for_rag, created_at, updated_at) VALUES ((SELECT interview_id FROM lg_interviews WHERE uuid = (SELECT uuid FROM lg_interviews WHERE interview_id = 9 LIMIT 1)), 'summary', 'Reflections on transitioning from a corporate engineering job at age 52 to open a local woodworking shop. It explores the financial fear and the emotional satisfaction of manual craft.', 'local-semantic-tfidf-v1', 'approved', 1, NOW(), NOW());
INSERT IGNORE INTO lg_knowledge_chunks (interview_id, content_type, anonymized_text, embedding_model, status, approved_for_rag, created_at, updated_at) VALUES ((SELECT interview_id FROM lg_interviews WHERE uuid = (SELECT uuid FROM lg_interviews WHERE interview_id = 9 LIMIT 1)), 'lesson', 'True career satisfaction comes from doing work where you can see the tangible results of your labor, rather than climbing a corporate ladder that feels empty.', 'local-semantic-tfidf-v1', 'approved', 1, NOW(), NOW());
INSERT IGNORE INTO lg_knowledge_chunks (interview_id, content_type, anonymized_text, embedding_model, status, approved_for_rag, created_at, updated_at) VALUES ((SELECT interview_id FROM lg_interviews WHERE uuid = (SELECT uuid FROM lg_interviews WHERE interview_id = 9 LIMIT 1)), 'turning_point', 'Deciding to leave a secure senior director role at a tech firm after realizing the stress was affecting my relationship with my children.', 'local-semantic-tfidf-v1', 'approved', 1, NOW(), NOW());
