INSERT IGNORE INTO lg_knowledge_chunks (interview_id, content_type, anonymized_text, embedding_model, status, approved_for_rag, created_at, updated_at) VALUES ((SELECT interview_id FROM lg_interviews WHERE uuid = (SELECT uuid FROM lg_interviews WHERE interview_id = 61 LIMIT 1)), 'advice', 'If you dream of changing fields later in life, apprentice yourself to an expert on weekends before making any permanent financial leap.', 'local-semantic-tfidf-v1', 'approved', 1, NOW(), NOW());
