INSERT IGNORE INTO lg_knowledge_chunks (interview_id, content_type, anonymized_text, embedding_model, status, approved_for_rag, created_at, updated_at) VALUES ((SELECT interview_id FROM lg_interviews WHERE uuid = (SELECT uuid FROM lg_interviews WHERE interview_id = 75 LIMIT 1)), 'summary', 'Recovering from complete financial bankruptcy at 46 after a retail business partnership collapsed under fraudulent debts. We lost our home and moved into a small basement apartment with our two children.', 'local-semantic-tfidf-v1', 'approved', 1, NOW(), NOW());
INSERT IGNORE INTO lg_knowledge_chunks (interview_id, content_type, anonymized_text, embedding_model, status, approved_for_rag, created_at, updated_at) VALUES ((SELECT interview_id FROM lg_interviews WHERE uuid = (SELECT uuid FROM lg_interviews WHERE interview_id = 75 LIMIT 1)), 'lesson', 'Your financial net worth has nothing to do with your human self-worth. Bankruptcy is a legal mechanism to reset, not a permanent moral failure.', 'local-semantic-tfidf-v1', 'approved', 1, NOW(), NOW());
INSERT IGNORE INTO lg_knowledge_chunks (interview_id, content_type, anonymized_text, embedding_model, status, approved_for_rag, created_at, updated_at) VALUES ((SELECT interview_id FROM lg_interviews WHERE uuid = (SELECT uuid FROM lg_interviews WHERE interview_id = 75 LIMIT 1)), 'turning_point', 'Attending a debt counseling workshop and learning to strip away all ego around status, cars, and material appearances.', 'local-semantic-tfidf-v1', 'approved', 1, NOW(), NOW());
