INSERT IGNORE INTO lg_knowledge_chunks (interview_id, content_type, anonymized_text, embedding_model, status, approved_for_rag, created_at, updated_at) VALUES ((SELECT interview_id FROM lg_interviews WHERE uuid = (SELECT uuid FROM lg_interviews WHERE interview_id = 76 LIMIT 1)), 'summary', 'Learning to invest conservatively after losing nearly 70% of life savings in a speculative stock market bubble during my late thirties.', 'local-semantic-tfidf-v1', 'approved', 1, NOW(), NOW());
INSERT IGNORE INTO lg_knowledge_chunks (interview_id, content_type, anonymized_text, embedding_model, status, approved_for_rag, created_at, updated_at) VALUES ((SELECT interview_id FROM lg_interviews WHERE uuid = (SELECT uuid FROM lg_interviews WHERE interview_id = 76 LIMIT 1)), 'lesson', 'Wealth building is supposed to be boring and methodical, like watching grass grow. The desire to get rich quickly is the surest recipe for financial devastation.', 'local-semantic-tfidf-v1', 'approved', 1, NOW(), NOW());
INSERT IGNORE INTO lg_knowledge_chunks (interview_id, content_type, anonymized_text, embedding_model, status, approved_for_rag, created_at, updated_at) VALUES ((SELECT interview_id FROM lg_interviews WHERE uuid = (SELECT uuid FROM lg_interviews WHERE interview_id = 76 LIMIT 1)), 'turning_point', 'Vowing never to chase hot tips, crypto hype, or high-risk schemes, shifting entirely to low-cost broad index funds and steady monthly compounding.', 'local-semantic-tfidf-v1', 'approved', 1, NOW(), NOW());
INSERT IGNORE INTO lg_knowledge_chunks (interview_id, content_type, anonymized_text, embedding_model, status, approved_for_rag, created_at, updated_at) VALUES ((SELECT interview_id FROM lg_interviews WHERE uuid = (SELECT uuid FROM lg_interviews WHERE interview_id = 76 LIMIT 1)), 'advice', 'Live on 75% of your income, automatically invest 15% in low-cost index funds, maintain a 6-month emergency buffer in cash, and ignore financial news sensationalism.', 'local-semantic-tfidf-v1', 'approved', 1, NOW(), NOW());
INSERT IGNORE INTO lg_knowledge_chunks (interview_id, content_type, anonymized_text, embedding_model, status, approved_for_rag, created_at, updated_at) VALUES ((SELECT interview_id FROM lg_interviews WHERE uuid = (SELECT uuid FROM lg_interviews WHERE interview_id = 76 LIMIT 1)), 'quote', 'Financial independence is not about buying luxury; it is about buying your freedom and autonomy from worry.', 'local-semantic-tfidf-v1', 'approved', 1, NOW(), NOW());
INSERT IGNORE INTO lg_knowledge_chunks (interview_id, content_type, anonymized_text, embedding_model, status, approved_for_rag, created_at, updated_at) VALUES ((SELECT interview_id FROM lg_interviews WHERE uuid = (SELECT uuid FROM lg_interviews WHERE interview_id = 77 LIMIT 1)), 'summary', 'The truth about homeownership versus renting learned over forty years. Experiencing both the pride of owning a family home and the hidden costs of property taxes, maintenance, interest, and roof replacements.', 'local-semantic-tfidf-v1', 'approved', 1, NOW(), NOW());
INSERT IGNORE INTO lg_knowledge_chunks (interview_id, content_type, anonymized_text, embedding_model, status, approved_for_rag, created_at, updated_at) VALUES ((SELECT interview_id FROM lg_interviews WHERE uuid = (SELECT uuid FROM lg_interviews WHERE interview_id = 77 LIMIT 1)), 'lesson', 'A primary residence is a lifestyle choice and shelter, not an investment miracle. Buying more house than you need enslaves you to a mortgage.', 'local-semantic-tfidf-v1', 'approved', 1, NOW(), NOW());
INSERT IGNORE INTO lg_knowledge_chunks (interview_id, content_type, anonymized_text, embedding_model, status, approved_for_rag, created_at, updated_at) VALUES ((SELECT interview_id FROM lg_interviews WHERE uuid = (SELECT uuid FROM lg_interviews WHERE interview_id = 77 LIMIT 1)), 'turning_point', 'Calculating the actual 30-year return on our primary residence and discovering that after interest and upkeep, simple index funds would have yielded double.', 'local-semantic-tfidf-v1', 'approved', 1, NOW(), NOW());
INSERT IGNORE INTO lg_knowledge_chunks (interview_id, content_type, anonymized_text, embedding_model, status, approved_for_rag, created_at, updated_at) VALUES ((SELECT interview_id FROM lg_interviews WHERE uuid = (SELECT uuid FROM lg_interviews WHERE interview_id = 77 LIMIT 1)), 'advice', 'Never stretch your budget to the maximum allowed by a bank mortgage officer. Buy or rent well below your means so unexpected repairs never create panic.', 'local-semantic-tfidf-v1', 'approved', 1, NOW(), NOW());
INSERT IGNORE INTO lg_knowledge_chunks (interview_id, content_type, anonymized_text, embedding_model, status, approved_for_rag, created_at, updated_at) VALUES ((SELECT interview_id FROM lg_interviews WHERE uuid = (SELECT uuid FROM lg_interviews WHERE interview_id = 77 LIMIT 1)), 'quote', 'A big house does not make a happy home; an affordable home with minimal stress makes a peaceful life.', 'local-semantic-tfidf-v1', 'approved', 1, NOW(), NOW());
INSERT IGNORE INTO lg_knowledge_chunks (interview_id, content_type, anonymized_text, embedding_model, status, approved_for_rag, created_at, updated_at) VALUES ((SELECT interview_id FROM lg_interviews WHERE uuid = (SELECT uuid FROM lg_interviews WHERE interview_id = 78 LIMIT 1)), 'summary', 'Overcoming chronic credit card debt and compulsive spending habits that originated from trying to impress friends and keep up with social circles.', 'local-semantic-tfidf-v1', 'approved', 1, NOW(), NOW());
INSERT IGNORE INTO lg_knowledge_chunks (interview_id, content_type, anonymized_text, embedding_model, status, approved_for_rag, created_at, updated_at) VALUES ((SELECT interview_id FROM lg_interviews WHERE uuid = (SELECT uuid FROM lg_interviews WHERE interview_id = 78 LIMIT 1)), 'lesson', 'Most people spend money they do not have to buy things they do not need to impress people they do not even like. True dignity is living debt-free.', 'local-semantic-tfidf-v1', 'approved', 1, NOW(), NOW());
INSERT IGNORE INTO lg_knowledge_chunks (interview_id, content_type, anonymized_text, embedding_model, status, approved_for_rag, created_at, updated_at) VALUES ((SELECT interview_id FROM lg_interviews WHERE uuid = (SELECT uuid FROM lg_interviews WHERE interview_id = 78 LIMIT 1)), 'turning_point', 'Cutting up five credit cards in front of a trusted friend and committing to an all-cash envelope budget for three straight years.', 'local-semantic-tfidf-v1', 'approved', 1, NOW(), NOW());
INSERT IGNORE INTO lg_knowledge_chunks (interview_id, content_type, anonymized_text, embedding_model, status, approved_for_rag, created_at, updated_at) VALUES ((SELECT interview_id FROM lg_interviews WHERE uuid = (SELECT uuid FROM lg_interviews WHERE interview_id = 78 LIMIT 1)), 'advice', 'Wait forty-eight hours before any non-essential purchase over fifty dollars. You will find that eight times out of ten, the urge evaporates completely.', 'local-semantic-tfidf-v1', 'approved', 1, NOW(), NOW());
INSERT IGNORE INTO lg_knowledge_chunks (interview_id, content_type, anonymized_text, embedding_model, status, approved_for_rag, created_at, updated_at) VALUES ((SELECT interview_id FROM lg_interviews WHERE uuid = (SELECT uuid FROM lg_interviews WHERE interview_id = 78 LIMIT 1)), 'quote', 'The day I stopped caring what strangers thought of my car was the day I became financially wealthy.', 'local-semantic-tfidf-v1', 'approved', 1, NOW(), NOW());
INSERT IGNORE INTO lg_knowledge_chunks (interview_id, content_type, anonymized_text, embedding_model, status, approved_for_rag, created_at, updated_at) VALUES ((SELECT interview_id FROM lg_interviews WHERE uuid = (SELECT uuid FROM lg_interviews WHERE interview_id = 79 LIMIT 1)), 'summary', 'Managing finances in retirement on a modest fixed pension and social security by mastering the art of joyful frugality and community resources.', 'local-semantic-tfidf-v1', 'approved', 1, NOW(), NOW());
INSERT IGNORE INTO lg_knowledge_chunks (interview_id, content_type, anonymized_text, embedding_model, status, approved_for_rag, created_at, updated_at) VALUES ((SELECT interview_id FROM lg_interviews WHERE uuid = (SELECT uuid FROM lg_interviews WHERE interview_id = 79 LIMIT 1)), 'lesson', 'You can live an extraordinarily rich and dignified life on modest means if your desires are simple and your social connections are strong.', 'local-semantic-tfidf-v1', 'approved', 1, NOW(), NOW());
INSERT IGNORE INTO lg_knowledge_chunks (interview_id, content_type, anonymized_text, embedding_model, status, approved_for_rag, created_at, updated_at) VALUES ((SELECT interview_id FROM lg_interviews WHERE uuid = (SELECT uuid FROM lg_interviews WHERE interview_id = 79 LIMIT 1)), 'turning_point', 'Discovering that local public libraries, community centers, walking clubs, and home cooking offered richer social connection than commercial entertainment.', 'local-semantic-tfidf-v1', 'approved', 1, NOW(), NOW());
INSERT IGNORE INTO lg_knowledge_chunks (interview_id, content_type, anonymized_text, embedding_model, status, approved_for_rag, created_at, updated_at) VALUES ((SELECT interview_id FROM lg_interviews WHERE uuid = (SELECT uuid FROM lg_interviews WHERE interview_id = 79 LIMIT 1)), 'advice', 'Cultivate free hobbies early: reading, gardening, hiking, volunteering, and playing music. They keep your mind sharp and your expenses negligible.', 'local-semantic-tfidf-v1', 'approved', 1, NOW(), NOW());
INSERT IGNORE INTO lg_knowledge_chunks (interview_id, content_type, anonymized_text, embedding_model, status, approved_for_rag, created_at, updated_at) VALUES ((SELECT interview_id FROM lg_interviews WHERE uuid = (SELECT uuid FROM lg_interviews WHERE interview_id = 79 LIMIT 1)), 'quote', 'Wealth consists not in having great possessions, but in having few wants.', 'local-semantic-tfidf-v1', 'approved', 1, NOW(), NOW());
INSERT IGNORE INTO lg_knowledge_chunks (interview_id, content_type, anonymized_text, embedding_model, status, approved_for_rag, created_at, updated_at) VALUES ((SELECT interview_id FROM lg_interviews WHERE uuid = (SELECT uuid FROM lg_interviews WHERE interview_id = 80 LIMIT 1)), 'summary', 'Surviving Stage 3 colon cancer diagnosis at age 49. Undergoing aggressive chemotherapy, surgery, and eighteen months of physical and emotional trauma.', 'local-semantic-tfidf-v1', 'approved', 1, NOW(), NOW());
INSERT IGNORE INTO lg_knowledge_chunks (interview_id, content_type, anonymized_text, embedding_model, status, approved_for_rag, created_at, updated_at) VALUES ((SELECT interview_id FROM lg_interviews WHERE uuid = (SELECT uuid FROM lg_interviews WHERE interview_id = 80 LIMIT 1)), 'lesson', 'A life-threatening diagnosis strips away all trivial worries. It clarifies in an instant who truly loves you and what truly matters in your remaining days.', 'local-semantic-tfidf-v1', 'approved', 1, NOW(), NOW());
INSERT IGNORE INTO lg_knowledge_chunks (interview_id, content_type, anonymized_text, embedding_model, status, approved_for_rag, created_at, updated_at) VALUES ((SELECT interview_id FROM lg_interviews WHERE uuid = (SELECT uuid FROM lg_interviews WHERE interview_id = 80 LIMIT 1)), 'turning_point', 'Realizing that medical treatment was only half the battle; maintaining mental hope, community connection, and daily gratitude was essential for survival.', 'local-semantic-tfidf-v1', 'approved', 1, NOW(), NOW());
INSERT IGNORE INTO lg_knowledge_chunks (interview_id, content_type, anonymized_text, embedding_model, status, approved_for_rag, created_at, updated_at) VALUES ((SELECT interview_id FROM lg_interviews WHERE uuid = (SELECT uuid FROM lg_interviews WHERE interview_id = 80 LIMIT 1)), 'advice', 'Never postpone routine health screenings, colonoscopies, or mammograms. Early detection is the literal difference between life and death.', 'local-semantic-tfidf-v1', 'approved', 1, NOW(), NOW());
INSERT IGNORE INTO lg_knowledge_chunks (interview_id, content_type, anonymized_text, embedding_model, status, approved_for_rag, created_at, updated_at) VALUES ((SELECT interview_id FROM lg_interviews WHERE uuid = (SELECT uuid FROM lg_interviews WHERE interview_id = 80 LIMIT 1)), 'quote', 'Before cancer, I had a thousand trivial problems; after cancer, I realized I only had one real problem—and that every sunrise was a gift.', 'local-semantic-tfidf-v1', 'approved', 1, NOW(), NOW());
INSERT IGNORE INTO lg_knowledge_chunks (interview_id, content_type, anonymized_text, embedding_model, status, approved_for_rag, created_at, updated_at) VALUES ((SELECT interview_id FROM lg_interviews WHERE uuid = (SELECT uuid FROM lg_interviews WHERE interview_id = 81 LIMIT 1)), 'summary', 'Recovering from a debilitating stroke at 58 that temporarily paralyzed my right side and impaired my speech. Facing months of grueling physical therapy.', 'local-semantic-tfidf-v1', 'approved', 1, NOW(), NOW());
INSERT IGNORE INTO lg_knowledge_chunks (interview_id, content_type, anonymized_text, embedding_model, status, approved_for_rag, created_at, updated_at) VALUES ((SELECT interview_id FROM lg_interviews WHERE uuid = (SELECT uuid FROM lg_interviews WHERE interview_id = 81 LIMIT 1)), 'lesson', 'The human brain possesses astonishing neuroplasticity and capacity to heal when sustained by daily, patient, relentless practice.', 'local-semantic-tfidf-v1', 'approved', 1, NOW(), NOW());
INSERT IGNORE INTO lg_knowledge_chunks (interview_id, content_type, anonymized_text, embedding_model, status, approved_for_rag, created_at, updated_at) VALUES ((SELECT interview_id FROM lg_interviews WHERE uuid = (SELECT uuid FROM lg_interviews WHERE interview_id = 81 LIMIT 1)), 'turning_point', 'Deciding to celebrate microscopic improvements—wiggling one toe, saying two clear words—instead of agonizing over what I could no longer do.', 'local-semantic-tfidf-v1', 'approved', 1, NOW(), NOW());
INSERT IGNORE INTO lg_knowledge_chunks (interview_id, content_type, anonymized_text, embedding_model, status, approved_for_rag, created_at, updated_at) VALUES ((SELECT interview_id FROM lg_interviews WHERE uuid = (SELECT uuid FROM lg_interviews WHERE interview_id = 81 LIMIT 1)), 'advice', 'Learn the warning signs of stroke immediately (FAST: Face drooping, Arm weakness, Speech difficulty, Time to call). Every minute counts.', 'local-semantic-tfidf-v1', 'approved', 1, NOW(), NOW());
INSERT IGNORE INTO lg_knowledge_chunks (interview_id, content_type, anonymized_text, embedding_model, status, approved_for_rag, created_at, updated_at) VALUES ((SELECT interview_id FROM lg_interviews WHERE uuid = (SELECT uuid FROM lg_interviews WHERE interview_id = 81 LIMIT 1)), 'quote', 'Recovery is not a sprint; it is ten thousand tiny stubborn steps taken when nobody is watching.', 'local-semantic-tfidf-v1', 'approved', 1, NOW(), NOW());
INSERT IGNORE INTO lg_knowledge_chunks (interview_id, content_type, anonymized_text, embedding_model, status, approved_for_rag, created_at, updated_at) VALUES ((SELECT interview_id FROM lg_interviews WHERE uuid = (SELECT uuid FROM lg_interviews WHERE interview_id = 82 LIMIT 1)), 'summary', 'Transforming personal health at 53 after being diagnosed with severe Type 2 diabetes, high cholesterol, and obesity. Dropped 65 pounds and reversed medication needs through whole-food nutrition and daily walking.', 'local-semantic-tfidf-v1', 'approved', 1, NOW(), NOW());
INSERT IGNORE INTO lg_knowledge_chunks (interview_id, content_type, anonymized_text, embedding_model, status, approved_for_rag, created_at, updated_at) VALUES ((SELECT interview_id FROM lg_interviews WHERE uuid = (SELECT uuid FROM lg_interviews WHERE interview_id = 82 LIMIT 1)), 'lesson', 'It is never too late to reclaim your vitality. Your body will respond with incredible vigor to consistent nutrition, movement, and sleep even in midlife.', 'local-semantic-tfidf-v1', 'approved', 1, NOW(), NOW());
INSERT IGNORE INTO lg_knowledge_chunks (interview_id, content_type, anonymized_text, embedding_model, status, approved_for_rag, created_at, updated_at) VALUES ((SELECT interview_id FROM lg_interviews WHERE uuid = (SELECT uuid FROM lg_interviews WHERE interview_id = 82 LIMIT 1)), 'turning_point', 'Watching my own father suffer severe diabetic complications and leg amputation, vowing that I would not put my children through the same trauma.', 'local-semantic-tfidf-v1', 'approved', 1, NOW(), NOW());
INSERT IGNORE INTO lg_knowledge_chunks (interview_id, content_type, anonymized_text, embedding_model, status, approved_for_rag, created_at, updated_at) VALUES ((SELECT interview_id FROM lg_interviews WHERE uuid = (SELECT uuid FROM lg_interviews WHERE interview_id = 82 LIMIT 1)), 'advice', 'Do not follow extreme fad diets. Focus on three sustainable pillars: walk 30 minutes every single day, eliminate liquid sugars, and cook meals from whole ingredients.', 'local-semantic-tfidf-v1', 'approved', 1, NOW(), NOW());
INSERT IGNORE INTO lg_knowledge_chunks (interview_id, content_type, anonymized_text, embedding_model, status, approved_for_rag, created_at, updated_at) VALUES ((SELECT interview_id FROM lg_interviews WHERE uuid = (SELECT uuid FROM lg_interviews WHERE interview_id = 82 LIMIT 1)), 'quote', 'Taking care of your health is the highest form of respect and gratitude you can give to your family and your future self.', 'local-semantic-tfidf-v1', 'approved', 1, NOW(), NOW());
INSERT IGNORE INTO lg_knowledge_chunks (interview_id, content_type, anonymized_text, embedding_model, status, approved_for_rag, created_at, updated_at) VALUES ((SELECT interview_id FROM lg_interviews WHERE uuid = (SELECT uuid FROM lg_interviews WHERE interview_id = 83 LIMIT 1)), 'summary', 'Learning to live with chronic autoimmune arthritis and persistent daily pain without succumbing to despair or bitterness.', 'local-semantic-tfidf-v1', 'approved', 1, NOW(), NOW());
INSERT IGNORE INTO lg_knowledge_chunks (interview_id, content_type, anonymized_text, embedding_model, status, approved_for_rag, created_at, updated_at) VALUES ((SELECT interview_id FROM lg_interviews WHERE uuid = (SELECT uuid FROM lg_interviews WHERE interview_id = 83 LIMIT 1)), 'lesson', 'Pain is an inevitable physical sensation, but misery and bitterness are mental narratives you have the power to dismantle.', 'local-semantic-tfidf-v1', 'approved', 1, NOW(), NOW());
INSERT IGNORE INTO lg_knowledge_chunks (interview_id, content_type, anonymized_text, embedding_model, status, approved_for_rag, created_at, updated_at) VALUES ((SELECT interview_id FROM lg_interviews WHERE uuid = (SELECT uuid FROM lg_interviews WHERE interview_id = 83 LIMIT 1)), 'turning_point', 'Practicing mindfulness-based stress reduction and learning to separate physical sensation from emotional suffering.', 'local-semantic-tfidf-v1', 'approved', 1, NOW(), NOW());
INSERT IGNORE INTO lg_knowledge_chunks (interview_id, content_type, anonymized_text, embedding_model, status, approved_for_rag, created_at, updated_at) VALUES ((SELECT interview_id FROM lg_interviews WHERE uuid = (SELECT uuid FROM lg_interviews WHERE interview_id = 83 LIMIT 1)), 'advice', 'Pace yourself. Do not overexert on good days only to crash for a week. Establish a steady rhythm of gentle activity and prioritize restorative sleep.', 'local-semantic-tfidf-v1', 'approved', 1, NOW(), NOW());
INSERT IGNORE INTO lg_knowledge_chunks (interview_id, content_type, anonymized_text, embedding_model, status, approved_for_rag, created_at, updated_at) VALUES ((SELECT interview_id FROM lg_interviews WHERE uuid = (SELECT uuid FROM lg_interviews WHERE interview_id = 83 LIMIT 1)), 'quote', 'My joints may be stiff, but my spirit refuses to be crippled.', 'local-semantic-tfidf-v1', 'approved', 1, NOW(), NOW());
INSERT IGNORE INTO lg_knowledge_chunks (interview_id, content_type, anonymized_text, embedding_model, status, approved_for_rag, created_at, updated_at) VALUES ((SELECT interview_id FROM lg_interviews WHERE uuid = (SELECT uuid FROM lg_interviews WHERE interview_id = 84 LIMIT 1)), 'summary', 'Embracing aging gracefully in my late seventies rather than fighting wrinkles and physical changes with anxiety.', 'local-semantic-tfidf-v1', 'approved', 1, NOW(), NOW());
INSERT IGNORE INTO lg_knowledge_chunks (interview_id, content_type, anonymized_text, embedding_model, status, approved_for_rag, created_at, updated_at) VALUES ((SELECT interview_id FROM lg_interviews WHERE uuid = (SELECT uuid FROM lg_interviews WHERE interview_id = 84 LIMIT 1)), 'lesson', 'Growing old is a privilege denied to millions. Wrinkles and gray hair are not defects; they are medals of endurance earned across a full life.', 'local-semantic-tfidf-v1', 'approved', 1, NOW(), NOW());
INSERT IGNORE INTO lg_knowledge_chunks (interview_id, content_type, anonymized_text, embedding_model, status, approved_for_rag, created_at, updated_at) VALUES ((SELECT interview_id FROM lg_interviews WHERE uuid = (SELECT uuid FROM lg_interviews WHERE interview_id = 84 LIMIT 1)), 'turning_point', 'Looking at a photograph of my seventy-fifth birthday and seeing the laugh lines as an honorable map of decades of love, sorrow, and joy.', 'local-semantic-tfidf-v1', 'approved', 1, NOW(), NOW());
INSERT IGNORE INTO lg_knowledge_chunks (interview_id, content_type, anonymized_text, embedding_model, status, approved_for_rag, created_at, updated_at) VALUES ((SELECT interview_id FROM lg_interviews WHERE uuid = (SELECT uuid FROM lg_interviews WHERE interview_id = 84 LIMIT 1)), 'advice', 'Protect your mobility and leg strength above all else. Squat, walk, stay flexible, and nourish friendships that keep your mind laughing.', 'local-semantic-tfidf-v1', 'approved', 1, NOW(), NOW());
INSERT IGNORE INTO lg_knowledge_chunks (interview_id, content_type, anonymized_text, embedding_model, status, approved_for_rag, created_at, updated_at) VALUES ((SELECT interview_id FROM lg_interviews WHERE uuid = (SELECT uuid FROM lg_interviews WHERE interview_id = 84 LIMIT 1)), 'quote', 'Do not regret growing older; it is an honor that many of our dearest friends never received.', 'local-semantic-tfidf-v1', 'approved', 1, NOW(), NOW());
INSERT IGNORE INTO lg_knowledge_chunks (interview_id, content_type, anonymized_text, embedding_model, status, approved_for_rag, created_at, updated_at) VALUES ((SELECT interview_id FROM lg_interviews WHERE uuid = (SELECT uuid FROM lg_interviews WHERE interview_id = 85 LIMIT 1)), 'summary', 'Navigating the devastating loss of my partner of thirty years to sudden cardiac arrest. For the first year, waking up every morning felt like an insurmountable weight of silence and emptiness.', 'local-semantic-tfidf-v1', 'approved', 1, NOW(), NOW());
INSERT IGNORE INTO lg_knowledge_chunks (interview_id, content_type, anonymized_text, embedding_model, status, approved_for_rag, created_at, updated_at) VALUES ((SELECT interview_id FROM lg_interviews WHERE uuid = (SELECT uuid FROM lg_interviews WHERE interview_id = 85 LIMIT 1)), 'lesson', 'Grief never shrinks; rather, your capacity for life expands around the grief. You do not move on from great love; you move forward carrying their memory with you.', 'local-semantic-tfidf-v1', 'approved', 1, NOW(), NOW());
INSERT IGNORE INTO lg_knowledge_chunks (interview_id, content_type, anonymized_text, embedding_model, status, approved_for_rag, created_at, updated_at) VALUES ((SELECT interview_id FROM lg_interviews WHERE uuid = (SELECT uuid FROM lg_interviews WHERE interview_id = 85 LIMIT 1)), 'turning_point', 'Joining a weekly bereavement walking group where others understood that grief does not follow a neat five-stage schedule, but comes in unpredictable waves.', 'local-semantic-tfidf-v1', 'approved', 1, NOW(), NOW());
INSERT IGNORE INTO lg_knowledge_chunks (interview_id, content_type, anonymized_text, embedding_model, status, approved_for_rag, created_at, updated_at) VALUES ((SELECT interview_id FROM lg_interviews WHERE uuid = (SELECT uuid FROM lg_interviews WHERE interview_id = 85 LIMIT 1)), 'advice', 'Do not let anyone rush your mourning. Accept the tears when they arrive, eat small healthy meals, sleep when you can, and accept the help of patient friends.', 'local-semantic-tfidf-v1', 'approved', 1, NOW(), NOW());
INSERT IGNORE INTO lg_knowledge_chunks (interview_id, content_type, anonymized_text, embedding_model, status, approved_for_rag, created_at, updated_at) VALUES ((SELECT interview_id FROM lg_interviews WHERE uuid = (SELECT uuid FROM lg_interviews WHERE interview_id = 85 LIMIT 1)), 'quote', 'Grief is simply love with nowhere left to go; when you channel that love into helping others, light returns to the room.', 'local-semantic-tfidf-v1', 'approved', 1, NOW(), NOW());
INSERT IGNORE INTO lg_knowledge_chunks (interview_id, content_type, anonymized_text, embedding_model, status, approved_for_rag, created_at, updated_at) VALUES ((SELECT interview_id FROM lg_interviews WHERE uuid = (SELECT uuid FROM lg_interviews WHERE interview_id = 86 LIMIT 1)), 'summary', 'Coping with the tragic death of an adult child in an automobile accident. Facing the unbearable disruption of the natural order of life.', 'local-semantic-tfidf-v1', 'approved', 1, NOW(), NOW());
INSERT IGNORE INTO lg_knowledge_chunks (interview_id, content_type, anonymized_text, embedding_model, status, approved_for_rag, created_at, updated_at) VALUES ((SELECT interview_id FROM lg_interviews WHERE uuid = (SELECT uuid FROM lg_interviews WHERE interview_id = 86 LIMIT 1)), 'lesson', 'Even in the deepest tragedy imaginable, the human spirit retains the freedom to choose how to respond and how to honor the memory of those we cherish.', 'local-semantic-tfidf-v1', 'approved', 1, NOW(), NOW());
INSERT IGNORE INTO lg_knowledge_chunks (interview_id, content_type, anonymized_text, embedding_model, status, approved_for_rag, created_at, updated_at) VALUES ((SELECT interview_id FROM lg_interviews WHERE uuid = (SELECT uuid FROM lg_interviews WHERE interview_id = 86 LIMIT 1)), 'turning_point', 'Realizing after two years of complete darkness that living as a paralyzed, bitter ghost would be a disservice to my child’s joyful memory.', 'local-semantic-tfidf-v1', 'approved', 1, NOW(), NOW());
INSERT IGNORE INTO lg_knowledge_chunks (interview_id, content_type, anonymized_text, embedding_model, status, approved_for_rag, created_at, updated_at) VALUES ((SELECT interview_id FROM lg_interviews WHERE uuid = (SELECT uuid FROM lg_interviews WHERE interview_id = 86 LIMIT 1)), 'advice', 'Seek compassionate professional trauma counseling. Connect with peer support organizations like Compassionate Friends where parents share the same road.', 'local-semantic-tfidf-v1', 'approved', 1, NOW(), NOW());
INSERT IGNORE INTO lg_knowledge_chunks (interview_id, content_type, anonymized_text, embedding_model, status, approved_for_rag, created_at, updated_at) VALUES ((SELECT interview_id FROM lg_interviews WHERE uuid = (SELECT uuid FROM lg_interviews WHERE interview_id = 86 LIMIT 1)), 'quote', 'I cannot bring my child back, but I can make sure the love they brought into this world continues through my hands.', 'local-semantic-tfidf-v1', 'approved', 1, NOW(), NOW());
INSERT IGNORE INTO lg_knowledge_chunks (interview_id, content_type, anonymized_text, embedding_model, status, approved_for_rag, created_at, updated_at) VALUES ((SELECT interview_id FROM lg_interviews WHERE uuid = (SELECT uuid FROM lg_interviews WHERE interview_id = 87 LIMIT 1)), 'summary', 'Dealing with the loss of a lifelong best friend who had been my confidant for forty-five years since elementary school.', 'local-semantic-tfidf-v1', 'approved', 1, NOW(), NOW());
INSERT IGNORE INTO lg_knowledge_chunks (interview_id, content_type, anonymized_text, embedding_model, status, approved_for_rag, created_at, updated_at) VALUES ((SELECT interview_id FROM lg_interviews WHERE uuid = (SELECT uuid FROM lg_interviews WHERE interview_id = 87 LIMIT 1)), 'lesson', 'Deep adult friendship is one of life’s rarest and most sublime treasures. When a true friend departs, a piece of your personal history goes with them.', 'local-semantic-tfidf-v1', 'approved', 1, NOW(), NOW());
INSERT IGNORE INTO lg_knowledge_chunks (interview_id, content_type, anonymized_text, embedding_model, status, approved_for_rag, created_at, updated_at) VALUES ((SELECT interview_id FROM lg_interviews WHERE uuid = (SELECT uuid FROM lg_interviews WHERE interview_id = 87 LIMIT 1)), 'turning_point', 'Compiling a scrapbook of all our letters, photographs, and inside jokes and presenting copies to their children and grandchildren.', 'local-semantic-tfidf-v1', 'approved', 1, NOW(), NOW());
INSERT IGNORE INTO lg_knowledge_chunks (interview_id, content_type, anonymized_text, embedding_model, status, approved_for_rag, created_at, updated_at) VALUES ((SELECT interview_id FROM lg_interviews WHERE uuid = (SELECT uuid FROM lg_interviews WHERE interview_id = 87 LIMIT 1)), 'advice', 'Never let weeks or months slip by without calling the friends who know your history. Say \"I love you\" and \"I appreciate you\" while they are still here to hear it.', 'local-semantic-tfidf-v1', 'approved', 1, NOW(), NOW());
INSERT IGNORE INTO lg_knowledge_chunks (interview_id, content_type, anonymized_text, embedding_model, status, approved_for_rag, created_at, updated_at) VALUES ((SELECT interview_id FROM lg_interviews WHERE uuid = (SELECT uuid FROM lg_interviews WHERE interview_id = 87 LIMIT 1)), 'quote', 'A true friend is a second self; losing them leaves an ache that only gratitude can soothe.', 'local-semantic-tfidf-v1', 'approved', 1, NOW(), NOW());
INSERT IGNORE INTO lg_knowledge_chunks (interview_id, content_type, anonymized_text, embedding_model, status, approved_for_rag, created_at, updated_at) VALUES ((SELECT interview_id FROM lg_interviews WHERE uuid = (SELECT uuid FROM lg_interviews WHERE interview_id = 88 LIMIT 1)), 'summary', 'Overcoming prolonged complicated bereavement after losing both elderly parents within six months of each other.', 'local-semantic-tfidf-v1', 'approved', 1, NOW(), NOW());
INSERT IGNORE INTO lg_knowledge_chunks (interview_id, content_type, anonymized_text, embedding_model, status, approved_for_rag, created_at, updated_at) VALUES ((SELECT interview_id FROM lg_interviews WHERE uuid = (SELECT uuid FROM lg_interviews WHERE interview_id = 88 LIMIT 1)), 'lesson', 'When your parents pass away, you suddenly become the oldest generation. It is your turn to provide the steady shelter, wisdom, and traditions for the youth.', 'local-semantic-tfidf-v1', 'approved', 1, NOW(), NOW());
INSERT IGNORE INTO lg_knowledge_chunks (interview_id, content_type, anonymized_text, embedding_model, status, approved_for_rag, created_at, updated_at) VALUES ((SELECT interview_id FROM lg_interviews WHERE uuid = (SELECT uuid FROM lg_interviews WHERE interview_id = 88 LIMIT 1)), 'turning_point', 'Emptying the family childhood home and realizing that physical possessions were not the vessel of their wisdom; their values were stored inside my own actions.', 'local-semantic-tfidf-v1', 'approved', 1, NOW(), NOW());
INSERT IGNORE INTO lg_knowledge_chunks (interview_id, content_type, anonymized_text, embedding_model, status, approved_for_rag, created_at, updated_at) VALUES ((SELECT interview_id FROM lg_interviews WHERE uuid = (SELECT uuid FROM lg_interviews WHERE interview_id = 88 LIMIT 1)), 'advice', 'Take audio recordings of your parents telling their stories before memory fades. Those voices will be priceless treasures when they are gone.', 'local-semantic-tfidf-v1', 'approved', 1, NOW(), NOW());
INSERT IGNORE INTO lg_knowledge_chunks (interview_id, content_type, anonymized_text, embedding_model, status, approved_for_rag, created_at, updated_at) VALUES ((SELECT interview_id FROM lg_interviews WHERE uuid = (SELECT uuid FROM lg_interviews WHERE interview_id = 88 LIMIT 1)), 'quote', 'Our parents never truly leave us as long as we live out the kindness and honesty they taught us at the kitchen table.', 'local-semantic-tfidf-v1', 'approved', 1, NOW(), NOW());
INSERT IGNORE INTO lg_knowledge_chunks (interview_id, content_type, anonymized_text, embedding_model, status, approved_for_rag, created_at, updated_at) VALUES ((SELECT interview_id FROM lg_interviews WHERE uuid = (SELECT uuid FROM lg_interviews WHERE interview_id = 89 LIMIT 1)), 'summary', 'Overcoming acute loneliness and social isolation after relocating to a new city alone at age 47 for work. Spending weekends with zero personal contact for six months.', 'local-semantic-tfidf-v1', 'approved', 1, NOW(), NOW());
INSERT IGNORE INTO lg_knowledge_chunks (interview_id, content_type, anonymized_text, embedding_model, status, approved_for_rag, created_at, updated_at) VALUES ((SELECT interview_id FROM lg_interviews WHERE uuid = (SELECT uuid FROM lg_interviews WHERE interview_id = 89 LIMIT 1)), 'lesson', 'Adult friendships are not formed through casual intentions; they require proximity, repeated unplanned interactions, and shared vulnerability over time.', 'local-semantic-tfidf-v1', 'approved', 1, NOW(), NOW());
INSERT IGNORE INTO lg_knowledge_chunks (interview_id, content_type, anonymized_text, embedding_model, status, approved_for_rag, created_at, updated_at) VALUES ((SELECT interview_id FROM lg_interviews WHERE uuid = (SELECT uuid FROM lg_interviews WHERE interview_id = 89 LIMIT 1)), 'turning_point', 'Deciding to volunteer every Saturday morning at a community food pantry and joining a local masters rowing club where attendance was expected.', 'local-semantic-tfidf-v1', 'approved', 1, NOW(), NOW());
INSERT IGNORE INTO lg_knowledge_chunks (interview_id, content_type, anonymized_text, embedding_model, status, approved_for_rag, created_at, updated_at) VALUES ((SELECT interview_id FROM lg_interviews WHERE uuid = (SELECT uuid FROM lg_interviews WHERE interview_id = 89 LIMIT 1)), 'advice', 'Do not wait for people to invite you. Find a weekly volunteer group or hobby club, attend faithfully for three months, and be the first to suggest coffee.', 'local-semantic-tfidf-v1', 'approved', 1, NOW(), NOW());
INSERT IGNORE INTO lg_knowledge_chunks (interview_id, content_type, anonymized_text, embedding_model, status, approved_for_rag, created_at, updated_at) VALUES ((SELECT interview_id FROM lg_interviews WHERE uuid = (SELECT uuid FROM lg_interviews WHERE interview_id = 89 LIMIT 1)), 'quote', 'To make a friend in your forties or fifties, you must be brave enough to be the one who reaches out first.', 'local-semantic-tfidf-v1', 'approved', 1, NOW(), NOW());
INSERT IGNORE INTO lg_knowledge_chunks (interview_id, content_type, anonymized_text, embedding_model, status, approved_for_rag, created_at, updated_at) VALUES ((SELECT interview_id FROM lg_interviews WHERE uuid = (SELECT uuid FROM lg_interviews WHERE interview_id = 90 LIMIT 1)), 'summary', 'Pruning toxic, one-sided friendships in midlife that drained emotional energy without reciprocity or genuine care.', 'local-semantic-tfidf-v1', 'approved', 1, NOW(), NOW());
INSERT IGNORE INTO lg_knowledge_chunks (interview_id, content_type, anonymized_text, embedding_model, status, approved_for_rag, created_at, updated_at) VALUES ((SELECT interview_id FROM lg_interviews WHERE uuid = (SELECT uuid FROM lg_interviews WHERE interview_id = 90 LIMIT 1)), 'lesson', 'Quality in friendship is infinitely more nourishing than quantity. Having two true friends who show up when you are in hospital is worth fifty social acquaintances.', 'local-semantic-tfidf-v1', 'approved', 1, NOW(), NOW());
INSERT IGNORE INTO lg_knowledge_chunks (interview_id, content_type, anonymized_text, embedding_model, status, approved_for_rag, created_at, updated_at) VALUES ((SELECT interview_id FROM lg_interviews WHERE uuid = (SELECT uuid FROM lg_interviews WHERE interview_id = 90 LIMIT 1)), 'turning_point', 'Realizing that whenever I stopped being the one who called and organized dinners, two long-time acquaintances never reached out once in an entire year.', 'local-semantic-tfidf-v1', 'approved', 1, NOW(), NOW());
INSERT IGNORE INTO lg_knowledge_chunks (interview_id, content_type, anonymized_text, embedding_model, status, approved_for_rag, created_at, updated_at) VALUES ((SELECT interview_id FROM lg_interviews WHERE uuid = (SELECT uuid FROM lg_interviews WHERE interview_id = 90 LIMIT 1)), 'advice', 'Stop drinking from empty cups. Notice who celebrates your victories and who only calls when they need emotional unloading or favors.', 'local-semantic-tfidf-v1', 'approved', 1, NOW(), NOW());
INSERT IGNORE INTO lg_knowledge_chunks (interview_id, content_type, anonymized_text, embedding_model, status, approved_for_rag, created_at, updated_at) VALUES ((SELECT interview_id FROM lg_interviews WHERE uuid = (SELECT uuid FROM lg_interviews WHERE interview_id = 90 LIMIT 1)), 'quote', 'A smaller circle filled with loyalty and honesty is ten times better than a crowded room full of performative friends.', 'local-semantic-tfidf-v1', 'approved', 1, NOW(), NOW());
INSERT IGNORE INTO lg_knowledge_chunks (interview_id, content_type, anonymized_text, embedding_model, status, approved_for_rag, created_at, updated_at) VALUES ((SELECT interview_id FROM lg_interviews WHERE uuid = (SELECT uuid FROM lg_interviews WHERE interview_id = 91 LIMIT 1)), 'summary', 'Building cross-generational friendships between people in their twenties and older adults in their seventies in a community arts workshop.', 'local-semantic-tfidf-v1', 'approved', 1, NOW(), NOW());
INSERT IGNORE INTO lg_knowledge_chunks (interview_id, content_type, anonymized_text, embedding_model, status, approved_for_rag, created_at, updated_at) VALUES ((SELECT interview_id FROM lg_interviews WHERE uuid = (SELECT uuid FROM lg_interviews WHERE interview_id = 91 LIMIT 1)), 'lesson', 'Age segregation impoverishes society. When young and old share stories and create things together, loneliness dissolves for both generations.', 'local-semantic-tfidf-v1', 'approved', 1, NOW(), NOW());
INSERT IGNORE INTO lg_knowledge_chunks (interview_id, content_type, anonymized_text, embedding_model, status, approved_for_rag, created_at, updated_at) VALUES ((SELECT interview_id FROM lg_interviews WHERE uuid = (SELECT uuid FROM lg_interviews WHERE interview_id = 91 LIMIT 1)), 'turning_point', 'Discovering that young people hunger for non-judgmental guidance, while older adults gain infectious energy and modern perspective from younger minds.', 'local-semantic-tfidf-v1', 'approved', 1, NOW(), NOW());
INSERT IGNORE INTO lg_knowledge_chunks (interview_id, content_type, anonymized_text, embedding_model, status, approved_for_rag, created_at, updated_at) VALUES ((SELECT interview_id FROM lg_interviews WHERE uuid = (SELECT uuid FROM lg_interviews WHERE interview_id = 91 LIMIT 1)), 'advice', 'Seek out conversations with people outside your demographic peer group. Young people bring vitality; older people bring perspective.', 'local-semantic-tfidf-v1', 'approved', 1, NOW(), NOW());
INSERT IGNORE INTO lg_knowledge_chunks (interview_id, content_type, anonymized_text, embedding_model, status, approved_for_rag, created_at, updated_at) VALUES ((SELECT interview_id FROM lg_interviews WHERE uuid = (SELECT uuid FROM lg_interviews WHERE interview_id = 91 LIMIT 1)), 'quote', 'The young need elders to show them the horizon; the elders need the young to remind them of the wonder at their feet.', 'local-semantic-tfidf-v1', 'approved', 1, NOW(), NOW());
INSERT IGNORE INTO lg_knowledge_chunks (interview_id, content_type, anonymized_text, embedding_model, status, approved_for_rag, created_at, updated_at) VALUES ((SELECT interview_id FROM lg_interviews WHERE uuid = (SELECT uuid FROM lg_interviews WHERE interview_id = 92 LIMIT 1)), 'summary', 'Overcoming decades of chronic generalized anxiety, rumination, and catastrophizing about future disasters that never arrived.', 'local-semantic-tfidf-v1', 'approved', 1, NOW(), NOW());
INSERT IGNORE INTO lg_knowledge_chunks (interview_id, content_type, anonymized_text, embedding_model, status, approved_for_rag, created_at, updated_at) VALUES ((SELECT interview_id FROM lg_interviews WHERE uuid = (SELECT uuid FROM lg_interviews WHERE interview_id = 92 LIMIT 1)), 'lesson', 'Most suffering happens entirely in our imagination, ruminating on a past that cannot be changed or worrying about a future that will never occur.', 'local-semantic-tfidf-v1', 'approved', 1, NOW(), NOW());
INSERT IGNORE INTO lg_knowledge_chunks (interview_id, content_type, anonymized_text, embedding_model, status, approved_for_rag, created_at, updated_at) VALUES ((SELECT interview_id FROM lg_interviews WHERE uuid = (SELECT uuid FROM lg_interviews WHERE interview_id = 92 LIMIT 1)), 'turning_point', 'Committing to a daily practice of ten minutes of silent breath meditation and maintaining a strict morning digital detox rule.', 'local-semantic-tfidf-v1', 'approved', 1, NOW(), NOW());
INSERT IGNORE INTO lg_knowledge_chunks (interview_id, content_type, anonymized_text, embedding_model, status, approved_for_rag, created_at, updated_at) VALUES ((SELECT interview_id FROM lg_interviews WHERE uuid = (SELECT uuid FROM lg_interviews WHERE interview_id = 92 LIMIT 1)), 'advice', 'Do not check news or social media for the first sixty minutes after waking. Step outside, drink water, feel morning sunlight, and breathe deeply.', 'local-semantic-tfidf-v1', 'approved', 1, NOW(), NOW());
INSERT IGNORE INTO lg_knowledge_chunks (interview_id, content_type, anonymized_text, embedding_model, status, approved_for_rag, created_at, updated_at) VALUES ((SELECT interview_id FROM lg_interviews WHERE uuid = (SELECT uuid FROM lg_interviews WHERE interview_id = 92 LIMIT 1)), 'quote', 'I have survived thousands of catastrophic emergencies in my mind, almost none of which ever actually occurred in real life.', 'local-semantic-tfidf-v1', 'approved', 1, NOW(), NOW());
INSERT IGNORE INTO lg_knowledge_chunks (interview_id, content_type, anonymized_text, embedding_model, status, approved_for_rag, created_at, updated_at) VALUES ((SELECT interview_id FROM lg_interviews WHERE uuid = (SELECT uuid FROM lg_interviews WHERE interview_id = 93 LIMIT 1)), 'summary', 'Recovering from severe clinical depression at age 44 through a combination of professional medical care, cognitive behavioral therapy, and daily walking.', 'local-semantic-tfidf-v1', 'approved', 1, NOW(), NOW());
INSERT IGNORE INTO lg_knowledge_chunks (interview_id, content_type, anonymized_text, embedding_model, status, approved_for_rag, created_at, updated_at) VALUES ((SELECT interview_id FROM lg_interviews WHERE uuid = (SELECT uuid FROM lg_interviews WHERE interview_id = 93 LIMIT 1)), 'lesson', 'Depression is an illness of brain chemistry and life stress, not a personal character defect. Seeking professional help is an act of profound courage.', 'local-semantic-tfidf-v1', 'approved', 1, NOW(), NOW());
INSERT IGNORE INTO lg_knowledge_chunks (interview_id, content_type, anonymized_text, embedding_model, status, approved_for_rag, created_at, updated_at) VALUES ((SELECT interview_id FROM lg_interviews WHERE uuid = (SELECT uuid FROM lg_interviews WHERE interview_id = 93 LIMIT 1)), 'turning_point', 'Letting go of the cultural stigma that seeking psychiatric medication and therapy was a sign of moral weakness, and asking for medical help.', 'local-semantic-tfidf-v1', 'approved', 1, NOW(), NOW());
INSERT IGNORE INTO lg_knowledge_chunks (interview_id, content_type, anonymized_text, embedding_model, status, approved_for_rag, created_at, updated_at) VALUES ((SELECT interview_id FROM lg_interviews WHERE uuid = (SELECT uuid FROM lg_interviews WHERE interview_id = 93 LIMIT 1)), 'advice', 'If you are struggling to get out of bed or feeling hopeless, reach out to a professional immediately. Tell one trusted person the complete truth today.', 'local-semantic-tfidf-v1', 'approved', 1, NOW(), NOW());
INSERT IGNORE INTO lg_knowledge_chunks (interview_id, content_type, anonymized_text, embedding_model, status, approved_for_rag, created_at, updated_at) VALUES ((SELECT interview_id FROM lg_interviews WHERE uuid = (SELECT uuid FROM lg_interviews WHERE interview_id = 93 LIMIT 1)), 'quote', 'Asking for help was not surrendering; it was refusing to let the darkness win.', 'local-semantic-tfidf-v1', 'approved', 1, NOW(), NOW());
INSERT IGNORE INTO lg_knowledge_chunks (interview_id, content_type, anonymized_text, embedding_model, status, approved_for_rag, created_at, updated_at) VALUES ((SELECT interview_id FROM lg_interviews WHERE uuid = (SELECT uuid FROM lg_interviews WHERE interview_id = 94 LIMIT 1)), 'summary', 'Overcoming chronic people-pleasing and inability to set boundaries that led to total exhaustion and resentment for twenty-five years.', 'local-semantic-tfidf-v1', 'approved', 1, NOW(), NOW());
INSERT IGNORE INTO lg_knowledge_chunks (interview_id, content_type, anonymized_text, embedding_model, status, approved_for_rag, created_at, updated_at) VALUES ((SELECT interview_id FROM lg_interviews WHERE uuid = (SELECT uuid FROM lg_interviews WHERE interview_id = 94 LIMIT 1)), 'lesson', 'When you say \"yes\" to something you do not want to do out of fear of conflict, you are saying \"no\" to your own health and your closest relationships.', 'local-semantic-tfidf-v1', 'approved', 1, NOW(), NOW());
INSERT IGNORE INTO lg_knowledge_chunks (interview_id, content_type, anonymized_text, embedding_model, status, approved_for_rag, created_at, updated_at) VALUES ((SELECT interview_id FROM lg_interviews WHERE uuid = (SELECT uuid FROM lg_interviews WHERE interview_id = 94 LIMIT 1)), 'turning_point', 'Learning in therapy that \"No\" is a complete sentence that does not require an elaborate apology or fabricated excuse.', 'local-semantic-tfidf-v1', 'approved', 1, NOW(), NOW());
INSERT IGNORE INTO lg_knowledge_chunks (interview_id, content_type, anonymized_text, embedding_model, status, approved_for_rag, created_at, updated_at) VALUES ((SELECT interview_id FROM lg_interviews WHERE uuid = (SELECT uuid FROM lg_interviews WHERE interview_id = 94 LIMIT 1)), 'advice', 'Practice pausing before accepting requests. Say: \"Let me check my calendar and get back to you tomorrow.\" This gives you space to evaluate truthfully.', 'local-semantic-tfidf-v1', 'approved', 1, NOW(), NOW());
INSERT IGNORE INTO lg_knowledge_chunks (interview_id, content_type, anonymized_text, embedding_model, status, approved_for_rag, created_at, updated_at) VALUES ((SELECT interview_id FROM lg_interviews WHERE uuid = (SELECT uuid FROM lg_interviews WHERE interview_id = 94 LIMIT 1)), 'quote', 'Setting boundaries feels like selfishness at first, but it is actually the foundation of genuine kindness.', 'local-semantic-tfidf-v1', 'approved', 1, NOW(), NOW());
INSERT IGNORE INTO lg_knowledge_chunks (interview_id, content_type, anonymized_text, embedding_model, status, approved_for_rag, created_at, updated_at) VALUES ((SELECT interview_id FROM lg_interviews WHERE uuid = (SELECT uuid FROM lg_interviews WHERE interview_id = 95 LIMIT 1)), 'summary', 'Learning to practice radical forgiveness toward an estranged business partner who embezzled company funds fifteen years ago.', 'local-semantic-tfidf-v1', 'approved', 1, NOW(), NOW());
INSERT IGNORE INTO lg_knowledge_chunks (interview_id, content_type, anonymized_text, embedding_model, status, approved_for_rag, created_at, updated_at) VALUES ((SELECT interview_id FROM lg_interviews WHERE uuid = (SELECT uuid FROM lg_interviews WHERE interview_id = 95 LIMIT 1)), 'lesson', 'Forgiveness does not mean reconciliation or condoning injustice; it means releasing your claim to vengeance so your own soul can be free.', 'local-semantic-tfidf-v1', 'approved', 1, NOW(), NOW());
INSERT IGNORE INTO lg_knowledge_chunks (interview_id, content_type, anonymized_text, embedding_model, status, approved_for_rag, created_at, updated_at) VALUES ((SELECT interview_id FROM lg_interviews WHERE uuid = (SELECT uuid FROM lg_interviews WHERE interview_id = 95 LIMIT 1)), 'turning_point', 'Realizing that nursing hatred and replaying the betrayal every morning was like drinking poison and expecting the other person to die.', 'local-semantic-tfidf-v1', 'approved', 1, NOW(), NOW());
INSERT IGNORE INTO lg_knowledge_chunks (interview_id, content_type, anonymized_text, embedding_model, status, approved_for_rag, created_at, updated_at) VALUES ((SELECT interview_id FROM lg_interviews WHERE uuid = (SELECT uuid FROM lg_interviews WHERE interview_id = 95 LIMIT 1)), 'advice', 'Forgive for your own sake, not theirs. Write a letter detailing all the anger, and then burn it safely as a symbolic release of the past.', 'local-semantic-tfidf-v1', 'approved', 1, NOW(), NOW());
INSERT IGNORE INTO lg_knowledge_chunks (interview_id, content_type, anonymized_text, embedding_model, status, approved_for_rag, created_at, updated_at) VALUES ((SELECT interview_id FROM lg_interviews WHERE uuid = (SELECT uuid FROM lg_interviews WHERE interview_id = 95 LIMIT 1)), 'quote', 'Holding onto anger is like clutching hot coal with the intent of throwing it at someone else; you are the one who gets burned.', 'local-semantic-tfidf-v1', 'approved', 1, NOW(), NOW());
INSERT IGNORE INTO lg_knowledge_chunks (interview_id, content_type, anonymized_text, embedding_model, status, approved_for_rag, created_at, updated_at) VALUES ((SELECT interview_id FROM lg_interviews WHERE uuid = (SELECT uuid FROM lg_interviews WHERE interview_id = 96 LIMIT 1)), 'summary', 'Overcoming severe identity loss and depression during the first year of retirement after forty years as a high school principal.', 'local-semantic-tfidf-v1', 'approved', 1, NOW(), NOW());
INSERT IGNORE INTO lg_knowledge_chunks (interview_id, content_type, anonymized_text, embedding_model, status, approved_for_rag, created_at, updated_at) VALUES ((SELECT interview_id FROM lg_interviews WHERE uuid = (SELECT uuid FROM lg_interviews WHERE interview_id = 96 LIMIT 1)), 'lesson', 'Retirement is not an endless vacation; humans need challenge, community responsibility, and a compelling reason to get out of bed each morning.', 'local-semantic-tfidf-v1', 'approved', 1, NOW(), NOW());
