INSERT IGNORE INTO lg_knowledge_chunks (interview_id, content_type, anonymized_text, embedding_model, status, approved_for_rag, created_at, updated_at) VALUES ((SELECT interview_id FROM lg_interviews WHERE uuid = (SELECT uuid FROM lg_interviews WHERE interview_id = 96 LIMIT 1)), 'advice', 'Plan your daily activities and social circles for retirement with the same diligence you put into your financial retirement savings.', 'local-semantic-tfidf-v1', 'approved', 1, NOW(), NOW());
INSERT IGNORE INTO lg_knowledge_chunks (interview_id, content_type, anonymized_text, embedding_model, status, approved_for_rag, created_at, updated_at) VALUES ((SELECT interview_id FROM lg_interviews WHERE uuid = (SELECT uuid FROM lg_interviews WHERE interview_id = 96 LIMIT 1)), 'quote', 'You do not retire to sit on a porch and watch the world go by; you retire so you can spend your best wisdom serving where it is needed most.', 'local-semantic-tfidf-v1', 'approved', 1, NOW(), NOW());
INSERT IGNORE INTO lg_knowledge_chunks (interview_id, content_type, anonymized_text, embedding_model, status, approved_for_rag, created_at, updated_at) VALUES ((SELECT interview_id FROM lg_interviews WHERE uuid = (SELECT uuid FROM lg_interviews WHERE interview_id = 97 LIMIT 1)), 'summary', 'Learning to paint with watercolors and exhibiting in a local gallery at age 67, having never picked up a paintbrush in my entire working life.', 'local-semantic-tfidf-v1', 'approved', 1, NOW(), NOW());
