INSERT IGNORE INTO lg_knowledge_chunks (interview_id, content_type, anonymized_text, embedding_model, status, approved_for_rag, created_at, updated_at) VALUES ((SELECT interview_id FROM lg_interviews WHERE uuid = (SELECT uuid FROM lg_interviews WHERE interview_id = 97 LIMIT 1)), 'advice', 'Take that music lesson, enroll in that creative writing course, or pick up that brush today. Stop telling yourself that your time has passed.', 'local-semantic-tfidf-v1', 'approved', 1, NOW(), NOW());
INSERT IGNORE INTO lg_knowledge_chunks (interview_id, content_type, anonymized_text, embedding_model, status, approved_for_rag, created_at, updated_at) VALUES ((SELECT interview_id FROM lg_interviews WHERE uuid = (SELECT uuid FROM lg_interviews WHERE interview_id = 97 LIMIT 1)), 'quote', 'The beginner’s mind at sixty-seven is the sweetest freedom on earth.', 'local-semantic-tfidf-v1', 'approved', 1, NOW(), NOW());
INSERT IGNORE INTO lg_knowledge_chunks (interview_id, content_type, anonymized_text, embedding_model, status, approved_for_rag, created_at, updated_at) VALUES ((SELECT interview_id FROM lg_interviews WHERE uuid = (SELECT uuid FROM lg_interviews WHERE interview_id = 98 LIMIT 1)), 'summary', 'Downsizing from a four-bedroom suburban house to a small garden cottage in retirement. Confronting forty years of accumulated possessions and clutter.', 'local-semantic-tfidf-v1', 'approved', 1, NOW(), NOW());
