INSERT IGNORE INTO lg_knowledge_chunks (interview_id, content_type, anonymized_text, embedding_model, status, approved_for_rag, created_at, updated_at) VALUES ((SELECT interview_id FROM lg_interviews WHERE uuid = (SELECT uuid FROM lg_interviews WHERE interview_id = 98 LIMIT 1)), 'advice', 'Begin decluttering ten years before you plan to move. Give heirlooms to loved ones while you are alive so you can enjoy their delight.', 'local-semantic-tfidf-v1', 'approved', 1, NOW(), NOW());
