INSERT IGNORE INTO lg_knowledge_chunks (interview_id, content_type, anonymized_text, embedding_model, status, approved_for_rag, created_at, updated_at) VALUES ((SELECT interview_id FROM lg_interviews WHERE uuid = (SELECT uuid FROM lg_interviews WHERE interview_id = 99 LIMIT 1)), 'summary', 'Wisdom gained at eighty looking back across eight decades of triumphs, losses, historical changes, and personal growth.', 'local-semantic-tfidf-v1', 'approved', 1, NOW(), NOW());
INSERT IGNORE INTO lg_knowledge_chunks (interview_id, content_type, anonymized_text, embedding_model, status, approved_for_rag, created_at, updated_at) VALUES ((SELECT interview_id FROM lg_interviews WHERE uuid = (SELECT uuid FROM lg_interviews WHERE interview_id = 99 LIMIT 1)), 'lesson', 'Life is extraordinarily brief. In the final accounting, you will never wish you had spent more time at the office; you will only wish you had loved more boldly.', 'local-semantic-tfidf-v1', 'approved', 1, NOW(), NOW());
