INSERT IGNORE INTO lg_knowledge_chunks (interview_id, content_type, anonymized_text, embedding_model, status, approved_for_rag, created_at, updated_at) VALUES ((SELECT interview_id FROM lg_interviews WHERE uuid = (SELECT uuid FROM lg_interviews WHERE interview_id = 99 LIMIT 1)), 'advice', 'Forgive quickly. Hug your loved ones tightly. Laugh at your mistakes. Take the trip. Do not take yourself too seriously.', 'local-semantic-tfidf-v1', 'approved', 1, NOW(), NOW());
