INSERT IGNORE INTO lg_knowledge_chunks (interview_id, content_type, anonymized_text, embedding_model, status, approved_for_rag, created_at, updated_at) VALUES ((SELECT interview_id FROM lg_interviews WHERE uuid = (SELECT uuid FROM lg_interviews WHERE interview_id = 216 LIMIT 1)), 'story_summary', 'I was working as a carpenter when I was 52, and I went through the experience of recovering from a massive financial setback. I discovered that the people who truly care about you will support your boundaries. That period fundamentally shifted how I approach challenges today.', 'local-semantic-tfidf-v1', 'approved', 1, NOW(), NOW());
